  from = terraform_data.old_name
  to   = terraform_data.renamed
}

module "group" {
  source   = "./modules/group"
  for_each = toset(["a", "b"])
  name     = each.key
}

data "terraform_remote_state" "pending" {
  backend    = "local"
  config     = { path = "remote.json" }
  depends_on = [terraform_data.created]
}

output "ids" {
  value = terraform_data.created[*].id
}

output "label" {
  value = "new"
}

output "token" {
  value     = var.token
  sensitive = true
}

