# 2 replace (delete,create and create,delete), 1 delete, 1 read (dependency pending),
# 2 no-op (one is the move). Nothing here is applied by the RE-01 scenario.

variable "db_password" {
  type      = string
  sensitive = true
}

variable "release" {
  type = string
}

variable "replicas" {
  type    = number
  default = 2
}

