  input = "release-${var.release}"
}

# update of a sensitive input
resource "terraform_data" "secret" {
  input = var.db_password
}

# no-op
resource "terraform_data" "stable" {
  input = "unchanged"
}

# no-op after a move
moved {
  from = terraform_data.legacy
  to   = terraform_data.renamed
}

